public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        // Read input and solve
        // Format likely: N towns, M edges, then edges, then sequence
        int N = sc.nextInt(); // towns
        int M = sc.nextInt(); // edges
        // adjacency list
        List<int[]>[] adj = new List[N];
        for(int i=0;i<N;i++) adj[i]=new ArrayList<>();
        for(int i=0;i<M;i++){
            int u=sc.nextInt()-1, v=sc.nextInt()-1, w=sc.nextInt();
            adj[u].add(new int[]{v,w});
            adj[v].add(new int[]{u,w});
        }
        int Q = sc.nextInt();
        int[] seq = new int[Q];
        for(int i=0;i<Q;i++) seq[i]=sc.nextInt()-1;
        // Dijkstra between each consecutive pair
        long total=0;
        for(int i=0;i<Q-1;i++){
            total+=dijkstra(seq[i],seq[i+1],N,adj);
        }
        System.out.println(total);
    }
    static long dijkstra(int src, int dst, int N, List<int[]>[] adj){
        long[] dist=new long[N];
        Arrays.fill(dist,Long.MAX_VALUE);
        dist[src]=0;
        PriorityQueue<long[]> pq=new PriorityQueue<>(Comparator.comparingLong(a->a[0]));
        pq.offer(new long[]{0,src});
        while(!pq.isEmpty()){
            long[] cur=pq.poll();
            long d=cur[0]; int u=(int)cur[1];
            if(d>dist[u]) continue;
            for(int[] e:adj[u]){
                int v=e[0]; long nd=d+e[1];
                if(nd<dist[v]){dist[v]=nd;pq.offer(new long[]{nd,v});}
            }
        }
        return dist[dst];
    }
}

import java.io.*;
