public class Main {
    static final long INF = Long.MAX_VALUE / 3;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());

        int n = Integer.parseInt(st.nextToken());  // number of vertices
        int m = Integer.parseInt(st.nextToken());  // number of edges

        // adjacency list for land roads (undirected)
        List<List<Edge>> landGraph = new ArrayList<>();
        for (int i = 0; i < n; i++) landGraph.add(new ArrayList<>());

        // adjacency list for sea routes (undirected)
        List<List<Edge>> seaGraph = new ArrayList<>();
        for (int i = 0; i < n; i++) seaGraph.add(new ArrayList<>());

        for (int i = 0; i < m; i++) {
            st = new StringTokenizer(br.readLine());
            int u = Integer.parseInt(st.nextToken()) - 1;
            int v = Integer.parseInt(st.nextToken()) - 1;
            int t = Integer.parseInt(st.nextToken());  // 0 = land, 1 = sea
            int c = Integer.parseInt(st.nextToken());  // travel time

            if (t == 0) {
                landGraph.get(u).add(new Edge(v, c));
                landGraph.get(v).add(new Edge(u, c));
            } else {
                seaGraph.get(u).add(new Edge(v, c));
                seaGraph.get(v).add(new Edge(u, c));
            }
        }

        st = new StringTokenizer(br.readLine());
        int r = Integer.parseInt(st.nextToken());
        int[] order = new int[r];
        for (int i = 0; i < r; i++) {
            order[i] = Integer.parseInt(st.nextToken()) - 1;
        }

        // Precompute all-pairs shortest paths on land and sea separately
        long[][] landDist = new long[n][n];
        long[][] seaDist = new long[n][n];

        for (int i = 0; i < n; i++) {
            Arrays.fill(landDist[i], INF);
            Arrays.fill(seaDist[i], INF);
            landDist[i][i] = 0;
            seaDist[i][i] = 0;
        }

        // Dijkstra from each node for land
        for (int s = 0; s < n; s++) {
            PriorityQueue<Node> pq = new PriorityQueue<>();
            pq.offer(new Node(s, 0));
            while (!pq.isEmpty()) {
                Node cur = pq.poll();
                int u = cur.idx;
                if (cur.dist > landDist[s][u]) continue;
                for (Edge e : landGraph.get(u)) {
                    long nd = landDist[s][u] + e.cost;
                    if (nd < landDist[s][e.to]) {
                        landDist[s][e.to] = nd;
                        pq.offer(new Node(e.to, nd));
                    }
                }
            }
        }

        // Dijkstra from each node for sea
        for (int s = 0; s < n; s++) {
            PriorityQueue<Node> pq = new PriorityQueue<>();
            pq.offer(new Node(s, 0));
            while (!pq.isEmpty()) {
                Node cur = pq.poll();
                int u = cur.idx;
                if (cur.dist > seaDist[s][u]) continue;
                for (Edge e : seaGraph.get(u)) {
                    long nd = seaDist[s][u] + e.cost;
                    if (nd < seaDist[s][e.to]) {
                        seaDist[s][e.to] = nd;
                        pq.offer(new Node(e.to, nd));
                    }
                }
            }
        }

        // Identify port towns (nodes that have at least one sea connection)
        boolean[] isPort = new boolean[n];
        for (int i = 0; i < n; i++) {
            if (!seaGraph.get(i).isEmpty()) isPort[i] = true;
        }

        // DP: dp[i][p] = min time to finish first i locations (0-indexed, up to i)
        // and be at port p after finishing the i-th location (i in [0, r-1])
        // p is a port town index, or we can also be at non-port towns? 
        // Actually we need to track the last port visited because sea travel requires returning to the last port.
        // But after delivering to a location, Mr. Rito may be at that location (if it's a port) or at some port.
        // Let's define dp[i][p] = min time to have visited order[0..i] and currently be at port p,
        // with the understanding that if the i-th location is itself a port, p can equal that location.
        // For non-port locations, we must have traveled by land from some port p to that location and back to p,
        // so after visiting a non-port, we are back at port p.

        // Since r <= 200 and n <= 200, we can have O(r * n^2) DP.

        // We'll compress port indices for efficiency
        List<Integer> portList = new ArrayList<>();
        for (int i = 0; i < n; i++) if (isPort[i]) portList.add(i);
        int P = portList.size();
        int[] portIdx = new int[n];
        Arrays.fill(portIdx, -1);
        for (int i = 0; i < P; i++) portIdx[portList.get(i)] = i;

        // If there are no ports, only land travel is possible
        if (P == 0) {
            long total = 0;
            for (int i = 0; i < r - 1; i++) {
                int u = order[i], v = order[i+1];
                if (landDist[u][v] >= INF) {
                    System.out.println(-1);
                    return;
                }
                total += landDist[u][v];
            }
            System.out.println(total);
            return;
        }

        // dp[i][p] for i-th location visited, being at port p
        long[][] dp = new long[r][P];
        for (int i = 0; i < r; i++) Arrays.fill(dp[i], INF);

        // Initialize for first location
        int start = order[0];
        for (int pi = 0; pi < P; pi++) {
            int p = portList.get(pi);
            // Option 1: start from port p, go to start by land, then back to p (if start not port)
            // Option 2: start from port p, go to start by sea if start is port and p == start? 
            // Actually we can start anywhere? Mr. Rito starts at town 1 per problem? 
            // Problem says "starting at town 1" but the first location is order[0].
            // We'll assume he can start at any port (since he can be at any port initially? 
            // Usually he starts at his home which is town 1. If town 1 is a port, that's fine.
            // But for generality, we allow starting from any port, but the problem might imply starting at town 1.
            // We'll handle by initializing dp[0][portIdx[order[0]]] = 0 if order[0] is a port, 
            // and also allow traveling from any port to order[0] and back.

            // Actually we should handle properly: He starts at town 1 (index 0). 
            // But the input order may not include town 1. We'll treat initial position as town 1.
            // Let's incorporate that.
        }

        // Better: handle starting at town 1 (node 0). If node 0 is not a port, we treat it specially.
        // We'll have dp with state (i, p) where p is port index. For i=0, we consider reaching order[0] from start=0.
        // If order[0] is a port, we can go by sea from some port? Actually from start 0 we can only go by land initially.
        // Let's do a simpler approach: treat starting point as a virtual port that is node 0 only if node 0 is port,
        // otherwise we must travel by land from node 0.

        // Instead, let's add a virtual starting state: we are at node 0 with "last port" being node 0 if it's a port,
        // otherwise we consider that we haven't used sea yet, so we can only travel by land until we reach a port.
        // This is getting complex. Let's just do DP over positions with state being current node (any node) and last port.
        // Since n <= 200 and r <= 200, O(r * n^2) is fine.

        // Let's redo DP with state (i, v) where v is current node after visiting order[i].
        // But we also need to know the last port for sea travel. 
        // We can incorporate that by forcing that whenever we use sea, we must return to the port.
        // So effectively, after visiting any node, we are either at a port (if we just arrived by sea or are at port)
        // or we are at a non-port but then we must have come from a port by land and will return to it.
        // So we can treat that we are always at a port after finishing a location, because if the location is non-port,
        // we go back to the port. So DP state can be (i, p) where p is the port we are at after finishing location i.
        // For the first location, if it's a port, we can be at that port with cost 0 (starting from town 1? 
        // We need to account for travel from town 1 to first location).

        // Let's handle initial travel from town 1 (node 0) to first location properly.
        // We'll compute a special initial cost for each possible starting port.

        // Actually, let's just say Mr. Rito starts at node 0. We'll compute min cost to reach order[0] and end at port p.
        // This can be done by considering:
        // - If order[0] is a port: we can go from 0 to order[0] by land, or from 0 to some port by land then sea to order[0].
        // - If order[0] is not a port: we must go from 0 to some port p by land, then from p to order[0] by land and back to p.

        // Let's compute initial costs for each port p.
        for (int pi = 0; pi < P; pi++) {
            int p = portList.get(pi);
            int first = order[0];
            // Travel from start 0 to first location, ending at port p
            if (first == p) {
                // Can come by land or sea? Since first is port, we can come by land from 0 to p,
                // or if 0 is port, we could go by sea? But we must end at p, so if we come by sea, we arrive at p.
                // But we can also come by land.
                long cost = landDist[0][p]; // land only
                if (landDist[0][p] >= INF) cost = INF;
                // Also by sea if 0 is port: but 0 may not be port. We'll just consider land for initial.
                dp[0][pi] = cost;
            } else {
                // first is not port p, so we must go from 0 to p (by land), then p to first by land, then back to p.
                long c1 = landDist[0][p];
                long c2 = landDist[p][first];
                long c3 = landDist[first][p];
                if (c1 >= INF || c2 >= INF || c3 >= INF) {
                    dp[0][pi] = INF;
                } else {
                    dp[0][pi] = c1 + c2 + c3;
                }
            }
        }

        // Also consider case where first location itself is a port and we start at that port directly?
        // That's covered by first == p with landDist[0][p].

        // Now DP for subsequent locations
        for (int i = 1; i < r; i++) {
            int cur = order[i];
            int prev = order[i-1];
            for (int pi = 0; pi < P; pi++) {
                int p = portList.get(pi);
                if (dp[i-1][pi] >= INF) continue;
                // From port p, we need to travel to cur and end at some port p2.
                // Three cases:
                // 1. cur is a port: we can go from p to cur by land, or by sea (if we go from p to some port by sea? 
                //    Actually sea travel: we can only use sea from port to port. So we can go p (port) -> sea -> some port q, 
                //    then land to cur? But cur is port, so we could go directly by sea from p to cur if there is sea route.
                //    Or we can go land from p to cur.
                //    After arriving at cur (port), we end at cur.
                // 2. cur is not a port: we must go from p to cur by land and back to some port p2.
                //    p2 can be p (same port) or another port q (if we go p -> land -> cur -> land -> q).
                //    But we could also go p -> sea -> q -> land -> cur -> land -> q? That would end at q.
                //    So we need to consider all possibilities.

                for (int pj = 0; pj < P; pj++) {
                    int q = portList.get(pj);
                    if (cur == q) {
                        // cur is port q
                        // Option A: land from p to q
                        long landCost = landDist[p][q];
                        if (landCost < INF) {
                            dp[i][pj] = Math.min(dp[i][pj], dp[i-1][pi] + landCost);
                        }
                        // Option B: sea from p to some port r, then land to q? No, if we use sea, we must end at the port we arrived by sea? 
                        // Actually rule: "if you use sea routes, you must end at the port town you arrived at after the sea travel."
                        // So if we go by sea from p to r, we must end at r. Then from r we can go by land to q (port).
                        // But then we end at q, not r. That would violate the rule because we used sea and ended at r, then moved by land.
                        // Wait: The rule says "when you use sea routes, you must return to the port town you last arrived at by sea before continuing by land."
                        // So you can go: port p -> sea -> port r (arrive by sea). Then you must return to r after any land travel.
                        // So if you go r -> land -> q (port), you must then go back to r by land before using sea again.
                        // So you could end at r after visiting q, not at q.
                        // So for ending at port q after visiting cur (which is q), you cannot have used sea in the last leg unless q is the sea arrival port.
                        // So if you use sea from p to q directly, you end at q. That's Option C.
                        // If you use sea from p to r (r != q), then you must go r -> land -> q -> land -> r, ending at r.
                        // So we need to consider ending at different ports.

                        // Option C: sea from p to q directly
                        long seaCost = seaDist[p][q];
                        if (seaCost < INF) {
                            dp[i][pj] = Math.min(dp[i][pj], dp[i-1][pi] + seaCost);
                        }

                        // Option D: sea from p to r, then land to q and back to r
                        for (int rIdx = 0; rIdx < P; rIdx++) {
                            int r = portList.get(rIdx);
                            long seaPart = seaDist[p][r];
                            if (seaPart >= INF) continue;
                            long landToQ = landDist[r][q];
                            long landBack = landDist[q][r];
                            if (landToQ >= INF || landBack >= INF) continue;
                            long total = seaPart + landToQ + landBack;
                            // End at r
                            dp[i][rIdx] = Math.min(dp[i][rIdx], dp[i-1][pi] + total);
                        }
                    } else {
                        // cur is not a port (q is some port we end at)
                        // We must go from p to cur by land, then back to q by land.
                        // But we could also involve sea: p -> sea -> r -> land -> cur -> land -> q
                        // Then must return to r? No, if we use sea to r, we must end at r after land travel, 
                        // so q must equal r to end at r. So for ending at q, if we use sea, we must have q as the sea arrival port.
                        // So either:
                        // Option E: land from p to cur, then land from cur to q
                        long land1 = landDist[p][cur];
                        long land2 = landDist[cur][q];
                        if (land1 < INF && land2 < INF) {
                            dp[i][pj] = Math.min(dp[i][pj], dp[i-1][pi] + land1 + land2);
                        }
                        // Option F: sea from p to q, then land to cur and back to q
                        long seaPQ = seaDist[p][q];
                        if (seaPQ < INF) {
                            long landToCur = landDist[q][cur];
                            long landBack = landDist[cur][q];
                            if (landToCur < INF && landBack < INF) {
                                dp[i][pj] = Math.min(dp[i][pj], dp[i-1][pi] + seaPQ + landToCur + landBack);
                            }
                        }
                        // Option G: sea from p to r (r != q), then land to cur, then land to q? 
                        // But then we used sea to r, so we must end at r. So q must equal r. Already covered by Option F with r=q.
                        // So no need.
                    }
                }
            }
        }

        long answer = INF;
        for (int pi = 0; pi < P; pi++) {
            answer = Math.min(answer, dp[r-1][pi]);
        }

        // Also consider possibility that we never use sea (if no ports or we stay on land)
        // But our DP already includes land-only paths because we can always stay at same port p and use land.
        // However if there are no ports in the path, we might have a state where we never visited a port?
        // Our DP requires ending at a port. But if the last location is not a port, we must end at some port.
        // That's fine.

        if (answer >= INF) {
            System.out.println(-1);
        } else {
            System.out.println(answer);
        }
    }

    static class Edge {
        int to;
