    static class Node implements Comparable<Node> {
        int idx;
        long dist;
        Node(int i, long d) { idx = i; dist = d; }
        public int compareTo(Node o) { return Long.compare(this.dist, o.dist); }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static final long INF = (long) 4e18;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();

        while (true) {
            int n = fs.nextInt();
            int m = fs.nextInt();
            if (n == Integer.MIN_VALUE) return; // no input
            if (n == 0 && m == 0) break;

            long[][] land = new long[n][n];
            long[][] sea = new long[n][n];

            for (int i = 0; i < n; i++) {
                Arrays.fill(land[i], INF);
                Arrays.fill(sea[i], INF);
                land[i][i] = 0;
                sea[i][i] = 0;
            }

            for (int i = 0; i < m; i++) {
                int x = fs.nextInt() - 1;
                int y = fs.nextInt() - 1;
                int t = fs.nextInt();
                String type = fs.next();
                if (type.charAt(0) == 'L') {
                    if (t < land[x][y]) {
                        land[x][y] = land[y][x] = t;
                    }
                } else {
                    if (t < sea[x][y]) {
                        sea[x][y] = sea[y][x] = t;
                    }
                }
            }

            // Floyd-Warshall for land and sea separately
            for (int k = 0; k < n; k++) {
                for (int i = 0; i < n; i++) {
                    if (land[i][k] == INF && sea[i][k] == INF) continue;
                    for (int j = 0; j < n; j++) {
                        if (land[i][k] != INF && land[k][j] != INF) {
                            long nd = land[i][k] + land[k][j];
                            if (nd < land[i][j]) land[i][j] = nd;
                        }
                        if (sea[i][k] != INF && sea[k][j] != INF) {
                            long nd = sea[i][k] + sea[k][j];
                            if (nd < sea[i][j]) sea[i][j] = nd;
                        }
                    }
                }
            }

            int r = fs.nextInt();
            int[] z = new int[r];
            for (int i = 0; i < r; i++) z[i] = fs.nextInt() - 1;

            // dp[i][p] = minimum time after visiting z[0..i], with boat currently at town p
            // After each target, Mr. Rito must be at that target, while the boat may remain at some port p.
            long[][] dp = new long[r][n];
            for (int i = 0; i < r; i++) Arrays.fill(dp[i], INF);

            // Initially, before first destination, both Mr. Rito and boat are at z[0]
            dp[0][z[0]] = 0;

            for (int i = 1; i < r; i++) {
                int prev = z[i - 1];
                int cur = z[i];

                for (int boatPos = 0; boatPos < n; boatPos++) {
                    long base = dp[i - 1][boatPos];
                    if (base == INF) continue;

                    // Option 1: move only by land, boat stays where it is
                    if (land[prev][cur] < INF) {
                        long nd = base + land[prev][cur];
                        if (nd < dp[i][boatPos]) dp[i][boatPos] = nd;
                    }

                    // Option 2: use the boat.
                    // Go by land from prev to some embark port a,
                    // move boat from boatPos to a by sea (possibly a == boatPos),
                    // sail from a to b,
                    // then go by land from b to cur.
                    // After this, boat ends at b.
                    //
                    // Equivalent transition from old boatPos to new boatPos=b:
                    // min over a:
                    // dp + land[prev][a] + sea[boatPos][a] + sea[a][b] + land[b][cur]
                    //
                    // Since sea shortest paths are already computed, sea[boatPos][a] + sea[a][b]
                    // is just a route moving boat from boatPos to b while meeting Rito at a.
                    // We implement straightforward O(n^3) per step, which is fine for this problem size.
                    for (int a = 0; a < n; a++) {
                        if (land[prev][a] == INF || sea[boatPos][a] == INF) continue;
                        long pref = base + land[prev][a] + sea[boatPos][a];
                        for (int b = 0; b < n; b++) {
                            if (sea[a][b] == INF || land[b][cur] == INF) continue;
                            long nd = pref + sea[a][b] + land[b][cur];
                            if (nd < dp[i][b]) dp[i][b] = nd;
                        }
                    }
                }
            }

            long ans = INF;
            for (int p = 0; p < n; p++) ans = Math.min(ans, dp[r - 1][p]);
            out.append(ans).append('\n');
        }

        System.out.print(out.toString());
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return Integer.MIN_VALUE;
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        String next() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ');

            StringBuilder sb = new StringBuilder();
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }
    }
}

