    for (int k = 0; k < n; k++) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (land_dist[i][k] + land_dist[k][j] < land_dist[i][j]) {
                    land_dist[i][j] = land_dist[i][k] + land_dist[k][j];
                }
            }
        }
    }

    // Floyd-Warshall for sea distances
    for (int k = 0; k < n; k++) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (sea_dist[i][k] + sea_dist[k][j] < sea_dist[i][j]) {
                    sea_dist[i][j] = sea_dist[i][k] + sea_dist[k][j];
                }
            }
        }
    }

    int r;
    scanf("%d", &r);
    int req[MAXN];
    for (int i = 0; i < r; i++) {
        scanf("%d", &req[i]);
        req[i]--;
    }

    // DP[i][j] = minimal time to visit first i+1 locations and end at port j
    // We'll keep track of last port visited
    static ll dp[MAXN][MAXN]; // dp[i][j] where i is index in req, j is current port
    // Initialize
    for (int i = 0; i < n; i++) {
        dp[0][i] = INF;
    }
    // From start location req[0], we can go to any port (including possibly itself if it's a port)
    // But we need to know which nodes are ports? Actually any node can be a port if it has sea routes.
    // We'll assume all nodes with sea_dist to others < INF are ports, but to be safe, we'll consider all nodes as potential ports.
    // The problem says "port towns" are those with boat connections. We'll just treat all nodes as possible ports.
    // Starting: we are at req[0], we can walk to any port j via land, then we are at port j.
    for (int j = 0; j < n; j++) {
        if (land_dist[req[0]][j] < INF) {
            dp[0][j] = land_dist[req[0]][j];
        }
    }
    // Also we could start at req[0] itself if it's already a port? That's covered by j=req[0] with 0 distance.

    for (int i = 1; i < r; i++) {
        int cur = req[i];
        int prev = req[i-1];
        for (int j = 0; j < n; j++) {
            dp[i][j] = INF;
            // Option 1: stay on land from previous location to current, without using sea
            // That means we were at some port k, then walked to prev, then walked to cur, then walked to port j
            // Actually we need to consider the sequence: after visiting prev, we are at port k (dp[i-1][k]).
            // Then from port k, we can walk to prev? Wait, careful: the sequence is: ... -> prev location -> cur location.
            // At step i-1, we have visited locations up to req[i-1] and we are at port k.
            // To visit req[i] = cur, we can:
            // - Walk from port k to prev (but we already visited prev, we are at port k, not at prev)
            // Actually we need to incorporate that we must visit the locations in order.
            // Better approach: We treat the process as: we are at some port, then we go to the next location via land, then optionally go to another port.
            // More precisely: After visiting req[i-1], we are at some port p. To visit req[i], we can walk from p to req[i] (land only), then walk from req[i] to some port q.
            // So dp[i][q] = min over p of dp[i-1][p] + land_dist[p][req[i]] + land_dist[req[i]][q]
            // But also we could use sea between ports: from port p, we take boat to some port p', then walk to req[i], then walk to q.
            // That is: dp[i][q] = min over p, p' of dp[i-1][p] + sea_dist[p][p'] + land_dist[p'][req[i]] + land_dist[req[i]][q]
            // However, the rule says: "if he uses a boat, he must return to the last visited port town before using the boat."
            // This means the sequence is: ... visit some location, then go to a port, then take boat, then from the destination port go to next location.
            // So the process is: we are at port p (after last visit), we can either:
            // 1) Walk directly to next location (via land) and then walk to port q (or stay at that location if it's a port)
            // 2) Take a boat from p to some port p', then walk to next location, then walk to port q.
            // But note: if we take a boat, we must have been at a port before (which we are, p is port), and after boat we arrive at p', which is also a port. Then we walk to location.
            // So the recurrence becomes:
            // dp[i][q] = min( min_p (dp[i-1][p] + land_dist[p][req[i]] + land_dist[req[i]][q]),
            //                min_p,p' (dp[i-1][p] + sea_dist[p][p'] + land_dist[p'][req[i]] + land_dist[req[i]][q]) )
            // But actually the first case is just a special case of the second with p'=p and sea_dist=0? But sea_dist might not be 0 for same port (it's 0 by our init). So we can just use the second form with sea_dist[p][p] = 0.
            // However, we must ensure that we don't use sea if not needed? It's fine because sea_dist[p][p]=0.
            // So we can write:
            // dp[i][q] = min_{p, p'} ( dp[i-1][p] + sea_dist[p][p'] + land_dist[p'][req[i]] + land_dist[req[i]][q] )
            // But this is O(n^3) per step, which is too slow (r up to 200, n up to 200 => 200*200^3 = 1.6e9).
            // We can optimize by precomputing best[p][q] = min_{p'} (sea_dist[p][p'] + land_dist[p'][req[i]]) for each i? But req[i] changes.
            // Actually we can compute for each i: best_start[p] = min_{p'} (sea_dist[p][p'] + land_dist[p'][req[i]])
            // Then dp[i][q] = min_p ( dp[i-1][p] + best_start[p] + land_dist[req[i]][q] )
            // That is O(n^2) per step.
            // Let's do that.
        }

        // Precompute best_start[p] = min_{p'} (sea_dist[p][p'] + land_dist[p'][cur])
        static ll best_start[MAXN];
        for (int p = 0; p < n; p++) {
            best_start[p] = INF;
            for (int p2 = 0; p2 < n; p2++) {
                ll val = (ll)sea_dist[p][p2] + land_dist[p2][cur];
                if (val < best_start[p]) best_start[p] = val;
            }
        }

        for (int q = 0; q < n; q++) {
            ll best = INF;
            for (int p = 0; p < n; p++) {
                ll val = dp[i-1][p] + best_start[p] + land_dist[cur][q];
                if (val < best) best = val;
            }
            dp[i][q] = best;
        }
    }

    // After visiting all locations, we don't need to end at a port, so answer is min over ports of dp[r-1][port]
    ll ans = INF;
    for (int j = 0; j < n; j++) {
        if (dp[r-1][j] < ans) ans = dp[r-1][j];
    }

    printf("%lld\n", ans);

    return 0;
}

#include <stdio.h>
