#define INF 0x3f3f3f3f

static int min_int(int a, int b) { return a < b ? a : b; }

int main(void) {
    int N, M;
    while (scanf("%d %d", &N, &M) == 2) {
        if (N == 0 && M == 0) break;

        int *isPort = (int *)calloc(N, sizeof(int));
        int *island = (int *)malloc(N * sizeof(int));

        for (int i = 0; i < N; i++) {
            int p, k;
            scanf("%d %d", &p, &k);
            isPort[i] = p;
            island[i] = k - 1; /* make islands 0-based */
        }

        int **land = (int **)malloc(N * sizeof(int *));
        int **sea  = (int **)malloc(N * sizeof(int *));
        for (int i = 0; i < N; i++) {
            land[i] = (int *)malloc(N * sizeof(int));
            sea[i]  = (int *)malloc(N * sizeof(int));
            for (int j = 0; j < N; j++) {
                land[i][j] = sea[i][j] = (i == j ? 0 : INF);
            }
        }

        for (int i = 0; i < M; i++) {
            int a, b, t;
            char s[8];
            scanf("%d %d %d %s", &a, &b, &t, s);
            --a; --b;
            if (s[0] == 'L' || s[0] == 'l') {
                if (t < land[a][b]) land[a][b] = land[b][a] = t;
            } else {
                if (t < sea[a][b]) sea[a][b] = sea[b][a] = t;
            }
        }

        /* Floyd-Warshall separately for land and sea */
        for (int k = 0; k < N; k++) {
            for (int i = 0; i < N; i++) {
                if (land[i][k] >= INF && sea[i][k] >= INF) continue;
                for (int j = 0; j < N; j++) {
                    if (land[i][k] < INF && land[k][j] < INF &&
                        land[i][j] > land[i][k] + land[k][j]) {
                        land[i][j] = land[i][k] + land[k][j];
                    }
                    if (sea[i][k] < INF && sea[k][j] < INF &&
                        sea[i][j] > sea[i][k] + sea[k][j]) {
                        sea[i][j] = sea[i][k] + sea[k][j];
                    }
                }
            }
        }

        int R;
        scanf("%d", &R);
        int *route = (int *)malloc(R * sizeof(int));
        for (int i = 0; i < R; i++) {
            scanf("%d", &route[i]);
            route[i]--;
        }

        /* DP:
           dp[i][p] = minimum time after visiting route[0..i], and currently the boat is at port town p.
           If route[i] is not a port, p is the port last used / where boat remains.
           If no sea has been used yet, we can think of p being any port on the same island as route[i]
           reachable only by land, but transitions below naturally handle it by initialization.
        */
        int **dp = (int **)malloc(R * sizeof(int *));
        for (int i = 0; i < R; i++) {
            dp[i] = (int *)malloc(N * sizeof(int));
            for (int j = 0; j < N; j++) dp[i][j] = INF;
        }

        /* Initialization:
           Start at route[0]. If boat is considered at port p, then route[0] must be reachable by land from p
           and p must be a port on the same island.
        */
        for (int p = 0; p < N; p++) {
            if (!isPort[p]) continue;
            if (island[p] == island[route[0]] && land[route[0]][p] < INF) {
                dp[0][p] = land[route[0]][p];
            }
        }

        for (int i = 0; i + 1 < R; i++) {
            int a = route[i];
            int b = route[i + 1];

            for (int p = 0; p < N; p++) {
                if (dp[i][p] >= INF || !isPort[p]) continue;

                /* Option 1: move only by land, boat stays at p.
                   Possible only if a and b are on same island and connected by land. */
                if (land[a][b] < INF) {
                    dp[i + 1][p] = min_int(dp[i + 1][p], dp[i][p] + land[a][b]);
                }

                /* Option 2: use boat.
                   Must go from current place a by land to current boat location p,
                   then by sea from p to some port q,
                   then by land from q to b.
                   After that boat stays at q.
                */
                if (land[a][p] < INF) {
                    for (int q = 0; q < N; q++) {
                        if (!isPort[q]) continue;
                        if (sea[p][q] < INF && land[q][b] < INF) {
                            int cand = dp[i][p] + land[a][p] + sea[p][q] + land[q][b];
                            if (cand < dp[i + 1][q]) dp[i + 1][q] = cand;
                        }
                    }
                }
            }
        }

        int ans = INF;
        for (int p = 0; p < N; p++) ans = min_int(ans, dp[R - 1][p]);
        printf("%d\n", ans);

        for (int i = 0; i < N; i++) {
            free(land[i]);
            free(sea[i]);
        }
        free(land);
        free(sea);
        free(isPort);
        free(island);
        for (int i = 0; i < R; i++) free(dp[i]);
        free(dp);
        free(route);
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
typedef pair<ll,int> pli;

// State: (current_node, last_port)
// Dijkstra for each leg

int main(){
    // Read input: nodes, edges (land/sea), port flags, sequence
    // Format assumed: N nodes, M edges, each edge has type (land/sea) and weight
    // Ports listed, then sequence

    int N, M;
    while(cin >> N >> M && (N||M)){
        vector<bool> isPort(N, false);
        vector<vector<pair<int,ll>>> land(N), sea(N);
        // read edges
        for(int i=0;i<M;i++){
            int u,v,t,w; cin>>u>>v>>t>>w; u--;v--;
            if(t==0){land[u].push_back({v,w});land[v].push_back({u,w});}
            else{sea[u].push_back({v,w});sea[v].push_back({u,w});}
        }
        int P; cin>>P;
        for(int i=0;i<P;i++){int p;cin>>p;p--;isPort[p]=true;}
        int Q; cin>>Q;
        vector<int> seq(Q);
        for(int i=0;i<Q;i++){cin>>seq[i];seq[i]--;}

        // Dijkstra: state=(node, last_port), last_port=-1 if none
        auto dijkstra=[&](int src, int lp)->vector<vector<ll>>{
            vector<vector<ll>> dist(N, vector<ll>(N+1, 1e18));
            priority_queue<tuple<ll,int,int>,vector<tuple<ll,int,int>>,greater<>> pq;
            dist[src][lp+1]=0; pq.push({0,src,lp});
            while(!pq.empty()){
                auto[d,u,p]=pq.top();pq.pop();
                if(d>dist[u][p+1])continue;
                for(auto[v,w]:land[u]){int np=isPort[v]?v:p;if(dist[u][p+1]+w<dist[v][np+1]){dist[v][np+1]=dist[u][p+1]+w;pq.push({dist[v][np+1],v,np});}}
                if(u==p)for(auto[v,w]:sea[u]){int np=v;if(dist[u][p+1]+w<dist[v][np+1]){dist[v][np+1]=dist[u][p+1]+w;pq.push({dist[v][np+1],v,np});}}
            }
            return dist;
        };

        ll ans=0;
        int cur=seq[0],lp=isPort[seq[0]]?seq[0]:-1;
        for(int i=1;i<Q;i++){
            auto dist=dijkstra(cur,lp);
            int nxt=seq[i];
            ll best=1e18; int blp=-1;
            for(int p=-1;p<N;p++){if(dist[nxt][p+1]<best){best=dist[nxt][p+1];blp=p;}}
            ans+=best; cur=nxt; lp=blp;
        }
        cout<<ans<<"\n";
    }
}

#include <bits/stdc++.h>
using namespace std;

const long long INF = 1e18;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    // land adjacency: distance by land between towns (port or not)
    vector<vector<long long>> land(n, vector<long long>(n, INF));
    for (int i = 0; i < n; i++) land[i][i] = 0;

    // sea adjacency: distance by sea between ports (only ports matter)
    // We'll store all edges, then run Floyd-Warshall on ports later.
    vector<tuple<int, int, long long>> sea_edges;
    vector<bool> is_port(n, false);

    for (int i = 0; i < m; i++) {
        int x, y, t;
        cin >> x >> y >> t;
        x--; y--;
        if (t == 0) {
            // land route
            land[x][y] = min(land[x][y], 1LL);
            land[y][x] = min(land[y][x], 1LL);
        } else {
            // sea route
            sea_edges.emplace_back(x, y, 1LL);
            is_port[x] = true;
            is_port[y] = true;
        }
    }

    int r;
    cin >> r;
    vector<int> dest(r);
    for (int i = 0; i < r; i++) {
        cin >> dest[i];
        dest[i]--;
    }

    // Floyd-Warshall on land distances (all vertices)
    for (int k = 0; k < n; k++) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (land[i][k] < INF && land[k][j] < INF)
                    land[i][j] = min(land[i][j], land[i][k] + land[k][j]);
            }
        }
    }

    // Gather port indices
    vector<int> ports;
    for (int i = 0; i < n; i++) {
        if (is_port[i]) ports.push_back(i);
    }
    int p = ports.size();
    // Map original index to port index
    vector<int> port_id(n, -1);
    for (int i = 0; i < p; i++) port_id[ports[i]] = i;

    // Sea distances between ports: initialize with INF
    vector<vector<long long>> sea(p, vector<long long>(p, INF));
    for (int i = 0; i < p; i++) sea[i][i] = 0;
    for (auto [x, y, w] : sea_edges) {
        int u = port_id[x], v = port_id[y];
        sea[u][v] = min(sea[u][v], w);
        sea[v][u] = min(sea[v][u], w);
    }
    // Floyd-Warshall on sea distances
    for (int k = 0; k < p; k++) {
        for (int i = 0; i < p; i++) {
            for (int j = 0; j < p; j++) {
                if (sea[i][k] < INF && sea[k][j] < INF)
                    sea[i][j] = min(sea[i][j], sea[i][k] + sea[k][j]);
            }
        }
    }

    // dp[i][j] = min time to reach dest[i] with Mr. Rito at port j (index in ports)
    vector<vector<long long>> dp(r, vector<long long>(p, INF));

    // Initialize for first destination
    int start = dest[0];
    // Option: arrive at start directly by land from any port? Actually start could be non-port.
    // We can consider starting from any port, but we start at "home"? The problem says Mr. Rito starts at town 1 (index 0). 
    // But we don't have a designated home port; we assume he can start at any port? Actually he starts at town 1 (index 0). 
    // However town 1 might not be a port. But the movement rules: before using sea, must be at a port. So initially he is at town 1.
    // We'll handle initial state differently: he can be at town 1 (non-port) and can move by land to dest[0] directly.
    // But dp state requires being at a port. So we need to allow a "virtual" starting port? 
    // Better approach: treat initial position as a special case: we can travel from town 0 to dest[0] by land only (no sea needed initially).
    // Then after that, we can decide to go to a port and continue.
    // Let's adjust: we can first compute the minimal time to reach dest[0] from start (town 0) without using sea, then from there we may go to a port.
    // Actually the DP should be: after visiting dest[i], we are at some port (or not? But rule says after using sea, must return to last port. 
    // However after visiting a town, we can be at that town (non-port) and then travel by land to a port to use sea. So the state "at a port" is only needed before using sea.
    // So we can define dp[i][j] = min time to have visited dest[0..i] and end at port j (meaning we are ready to take a sea route next, i.e., we are at port j).
    // For transitions, we consider two cases:
    // 1) From dest[i] we go by land to some port k, then by sea to port j, then by land to dest[i+1] (or we could go directly by land from dest[i] to dest[i+1] without using sea)
    // But we must ensure that after visiting dest[i+1], we end at port j (ready for next sea). Actually the state after visiting dest[i+1] should end at a port (if we plan to use sea later) or we could end at dest[i+1] itself if no more sea? 
    // The DP approach: dp[i][j] = min time after visiting first i+1 destinations and last port visited (i.e., current port location) is ports[j].
    // Transition: from dp[i][j] (at port j after dest[i]), we want to go to dest[i+1] and then to some port k. 
    // But careful: after visiting dest[i], we are at port j (meaning we just arrived at port j after delivering to dest[i]? Actually we must have delivered to dest[i] and then traveled to port j by land. 
    // So dp[i][j] includes time to deliver to dest[i] and then go to port j.
    // Then to go to dest[i+1], we can either:
    //   a) Travel by land from port j to dest[i+1] (no sea), then from dest[i+1] go by land to port k. Cost: land[ports[j]][dest[i+1]] + land[dest[i+1]][ports[k]].
    //   b) Travel by sea: from port j go by sea to some port j2, then by land to dest[i+1], then by land to port k. Cost: sea[j][j2] + land[ports[j2]][dest[i+1]] + land[dest[i+1]][ports[k]].
    // We can combine: essentially from port j to dest[i+1] we can use either direct land or sea+land, and then from dest[i+1] to port k by land.
    // So we can precompute best time from port j to dest[i+1] (allowing sea then land): best_to_dest[i+1][j] = min(land[ports[j]][dest[i+1]], min over ports j2 of sea[j][j2] + land[ports[j2]][dest[i+1]]).
    // Then transition: dp[i+1][k] = min over j of dp[i][j] + best_to_dest[i+1][j] + land[dest[i+1]][ports[k]].

    // But we also need to consider the initial state: before any destination, Mr. Rito is at town 0. We can consider dp[-1] as being at town 0 (not necessarily a port). 
    // So for the first destination, we can compute best time to go from town 0 to dest[0] and then to port k.
    // best_from_start_to_dest[0] = min(land[0][dest[0]], min over ports j2 of land[0][ports[j2]] + sea[j2][?] + land[?][dest[0]]? Actually from start we can go by land to a port, then sea, then land to dest[0]. 
    // So we can compute best time from start (town 0) to dest[0] allowing any combination: best_start_to_dest0 = min(land[0][dest[0]], min_{j2,j3} land[0][ports[j2]] + sea[j2][j3] + land[ports[j3]][dest[0]]).
    // But note that after reaching dest[0], we need to end at a port k for dp state. So initial dp[0][k] = best_start_to_dest0 + land[dest[0]][ports[k]].

    // However we also have the option to never use sea at all: then we just travel by land from start through all destinations in order. We'll handle that separately as a candidate answer.

    // Precompute best_to_dest[i][j] = min time from port j to dest[i] (allowing sea+land)
    vector<vector<long long>> best_to_dest(r, vector<long long>(p, INF));
    for (int i = 0; i < r; i++) {
        int d = dest[i];
        for (int j = 0; j < p; j++) {
            long long best = land[ports[j]][d];
            for (int j2 = 0; j2 < p; j2++) {
                if (sea[j][j2] < INF && land[ports[j2]][d] < INF) {
                    best = min(best, sea[j][j2] + land[ports[j2]][d]);
                }
            }
            best_to_dest[i][j] = best;
        }
    }

    // Precompute best from start (town 0) to dest[i] (allowing sea+land)
    vector<long long> best_start_to_dest(r, INF);
    for (int i = 0; i < r; i++) {
        int d = dest[i];
        long long best = land[0][d];
        for (int j2 = 0; j2 < p; j2++) {
            if (land[0][ports[j2]] < INF) {
                best = min(best, land[0][ports[j2]] + best_to_dest[i][j2]);
            }
        }
        best_start_to_dest[i] = best;
    }

    // Initialize dp for first destination
    for (int k = 0; k < p; k++) {
        if (best_start_to_dest[0] < INF && land[dest[0]][ports[k]] < INF) {
            dp[0][k] = best_start_to_dest[0] + land[dest[0]][ports[k]];
        }
    }

    // Fill dp
    for (int i = 0; i < r - 1; i++) {
        for (int j = 0; j < p; j++) {
            if (dp[i][j] >= INF) continue;
            for (int k = 0; k < p; k++) {
                long long cost = dp[i][j] + best_to_dest[i+1][j] + land[dest[i+1]][ports[k]];
                if (cost < dp[i+1][k]) {
                    dp[i+1][k] = cost;
                }
            }
        }
    }

    // Answer: after last destination, we don't need to be at a port. So best is min over k of dp[r-1][k] (we end at port k) but we could also end at dest[r-1] without going to port.
    // Also we could have never used sea: just land from start through all destinations.
    long long ans = INF;
    // Option 1: pure land route from start through all destinations in order
    long long pure_land = 0;
    int cur = 0;
    bool ok = true;
    for (int i = 0; i < r; i++) {
        if (land[cur][dest[i]] >= INF) { ok = false; break; }
        pure_land += land[cur][dest[i]];
        cur = dest[i];
    }
    if (ok) ans = min(ans, pure_land);

    // Option 2: end at some port after last destination (i.e., we went to a port after last dest)
    for (int k = 0; k < p; k++) {
        ans = min(ans, dp[r-1][k]);
    }

    // Option 3: we might have used sea for some segments but after last dest we don't go to a port. 
    // That is covered by dp state? Actually dp state requires ending at port. So we need to consider not going to port after last dest.
    // We can compute alternative: after last dest, we don't need to go to port. So we can consider dp[i][j] + best_to_dest_last[j] (without adding land to port).
    // But careful: best_to_dest_last[j] already includes going from port j to dest[last] (allowing sea). So we need to consider from dp[i][j] we go to dest[i+1] and stop there.
    // So we should also compute a separate DP that ends at destination without port.
    // Let's adjust: we can define dp2[i][j] = min time to have visited dest[0..i] and be at port j (ready for next sea). Then for final answer, we can take min over j of dp2[r-1][j] (end at port) OR for each i, we can consider going from dp2[i][j] to dest[i+1] and stop (no port after). But we already have best_to_dest for that.
    // Simpler: we can compute answer as min over j of (dp[r-1][j] - land[dest[r-1]][ports[j]])? No, because dp includes land to port after last dest. So we can compute ans2 = min over j of (dp[r-1][j] - land[dest[r-1]][ports[j]]) but that might be negative? Actually dp[r-1][j] includes land[dest[r-1]][ports[j]], so subtracting gives time to reach dest[r-1] and be at port j? Wait dp[r-1][j] = time to have visited dest[0..r-1] and then go to port j. So time to just visit dest[r-1] without going to port j is dp[r-1][j] - land[dest[r-1]][ports[j]]. But that assumes we actually went to port j after dest[r-1]; we could have chosen not to. So the minimal time to finish at dest[r-1] is min over j of (dp[r-1][j] - land[dest[r-1]][ports[j]]). However we also need to consider the case where we never used any sea after some point, so we might have ended at dest[r-1] directly from a previous state without going to port. That is covered by dp[i][j] + best_to_dest[i+1][j] for i = r-2, but we didn't store that. So we can compute an additional DP that tracks ending at destination directly.

    // Let's implement a cleaner DP: dp[i][j] = min time to have visited dest[0..i] and end at port j (i.e., at port after visiting dest[i]).
    // Then we also compute best_end[i] = min time to have visited dest[0..i] and end at dest[i] (no port after). This can be computed as:
    // best_end[0] = best_start_to_dest[0] (time to reach dest[0] from start)
    // For i>0: best_end[i] = min( min_j dp[i-1][j] + best_to_dest[i][j] , best_end[i-1] + land[dest[i-1]][dest[i]] )
    // Actually best_end[i-1] + land[dest[i-1]][dest[i]] is the pure land continuation.
    // Also we could have from dp[i-1][j] we go by land from port j to dest[i] directly (no sea) which is already in best_to_dest[i][j] (since it includes land[ports[j]][dest[i]]). So that's fine.
    // Then final answer = min(best_end[r-1], min_j dp[r-1][j]).

    vector<long long> best_end(r, INF);
    // Initialize first
    best_end[0] = best_start_to_dest[0];
    for (int i = 1; i < r; i++) {
        // from previous end at dest[i-1] by land
        if (best_end[i-1] < INF && land[dest[i-1]][dest[i]] < INF) {
            best_end[i] = min(best_end[i], best_end[i-1] + land[dest[i-1]][dest[i]]);
        }
        // from previous port state
        for (int j = 0; j < p; j++) {
            if (dp[i-1][j] < INF && best_to_dest[i][j] < INF) {
                best_end[i] = min(best_end[i], dp[i-1][j] + best_to_dest[i][j]);
            }
        }
    }

    ans = min(ans, best_end[r-1]);
    for (int j = 0; j < p; j++) {
        ans = min(ans, dp[r-1][j]);
    }

    cout << ans << "\n";

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

static const long long INF = (1LL << 60);

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    while (cin >> n >> m) {
        vector<vector<long long>> dist(n, vector<long long>(n, INF));
        for (int i = 0; i < n; ++i) dist[i][i] = 0;

        for (int i = 0; i < m; ++i) {
            int x, y, t;
            char c;
            cin >> x >> y >> t >> c;
            --x; --y;
            dist[x][y] = min(dist[x][y], (long long)t);
            dist[y][x] = min(dist[y][x], (long long)t);
        }

        // All-pairs shortest paths on the full graph.
        for (int k = 0; k < n; ++k) {
            for (int i = 0; i < n; ++i) {
                if (dist[i][k] == INF) continue;
                for (int j = 0; j < n; ++j) {
                    if (dist[k][j] == INF) continue;
                    long long nd = dist[i][k] + dist[k][j];
                    if (nd < dist[i][j]) dist[i][j] = nd;
                }
            }
        }

        int r;
        cin >> r;
        vector<int> z(r);
        for (int i = 0; i < r; ++i) {
            cin >> z[i];
            --z[i];
        }

        // dp[i][p]:
        // after visiting z[0..i] in order, and currently being at z[i],
        // the boat is at town p (the last port where it was left / returned to).
        vector<vector<long long>> dp(r, vector<long long>(n, INF));

        // Initially, after visiting z[0], if boat is at p, we must have gone
        // from z[0] to p and back to z[0] only if needed? Actually boat position
        // is relevant only after finishing at z[i]. Since movement by sea requires
        // being at the same port as the boat and returning to the destination port,
        // the standard recurrence becomes:
        // dp[0][p] = dist[z[0]][p]
        // interpreted as: Mr. Rito is at z[0], boat is at p after potentially
        // moving it there while ending at z[0]. This matches the known solution.
        for (int p = 0; p < n; ++p) dp[0][p] = dist[z[0]][p];

        for (int i = 1; i < r; ++i) {
            for (int p = 0; p < n; ++p) {
                if (dp[i - 1][p] == INF) continue;

                // Option 1: move by land only from z[i-1] to z[i], boat stays at p.
                dp[i][p] = min(dp[i][p], dp[i - 1][p] + dist[z[i - 1]][z[i]]);

                // Option 2: use the boat.
                // Go from z[i-1] to current boat location p,
                // move boat from p to q,
                // then go from q to z[i].
                for (int q = 0; q < n; ++q) {
                    if (dist[p][q] == INF || dist[q][z[i]] == INF || dist[z[i - 1]][p] == INF) continue;
                    long long cand = dp[i - 1][p] + dist[z[i - 1]][p] + dist[p][q] + dist[q][z[i]];
                    if (cand < dp[i][q]) dp[i][q] = cand;
                }
            }
        }

        long long ans = INF;
        for (int p = 0; p < n; ++p) ans = min(ans, dp[r - 1][p]);
        cout << ans << '\n';
    }

    return 0;
}
